SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "资治通鉴·后唐纪三", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/3ebe2df2/content/books/zizhi-tongjian/vol-274/year-0925/part-03/sources/library/tongjian-274-925-year-end/source.txt", "note": "《资治通鉴》后唐纪三，段落 zizhi-tongjian-a63549944a71-p003258；电子底本待考，分段待核", "id": "ff20e8f2-9e3c-5a79-a8c4-271b07aa9b0c"}, {"title": "资治通鉴·后唐纪三", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/0291ff48/content/books/zizhi-tongjian/vol-274/year-0926/part-02/sources/library/tongjian-274-926-palace-guard/source.txt", "note": "《资治通鉴》后唐纪三，段落 zizhi-tongjian-a63549944a71-p003262；电子底本待考，分段待核", "id": "85b2130d-d9ba-56c0-b1c6-4529ae26e067"}, {"title": "资治通鉴·后唐纪三", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/91a1ec5d/content/books/zizhi-tongjian/vol-274/year-0926/part-01/sources/library/tongjian-274-926-yedu/source.txt", "note": "《资治通鉴》后唐纪三，段落 zizhi-tongjian-a63549944a71-p003261；电子底本待考，分段待核", "id": "e86e455b-1006-58ae-a713-0d783ef5cddf"}, {"title": "资治通鉴·后唐纪四", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/60d249b7/content/books/zizhi-tongjian/vol-275/year-0926/part-01/sources/library/tongjian-275-926-regency/source.txt", "note": "《资治通鉴》后唐纪四，段落 zizhi-tongjian-a63549944a71-p003269；电子底本待考，分段待核", "id": "23947e13-c031-56b8-9ffa-2b1446607f3e"}, {"title": "资治通鉴·后唐纪三", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/8ecc7ee3/content/books/zizhi-tongjian/vol-274/year-0926/part-03/sources/library/tongjian-274-926-capture-and-monitors/source.txt", "note": "《资治通鉴》后唐纪三，段落 zizhi-tong