INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "李崧", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "李崧是饶阳人，曾任都统推官。926年，李继岌未经诏令杀死大将后，他提出反对，随后召集书吏伪造敕书，使军中局势大体安定。", "biography": null, "status": "draft", "id": "42727c37-29c7-534f-b0f7-900992c16def"}, {"name": "李继岌", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "李继岌曾率后唐军平定前蜀，受封魏王，派韩珙等押运蜀地财物。此事属于927年记事中的追叙。", "biography": null, "status": "draft", "id": "d160654e-338c-57b1-9759-208ae0af8250"}, {"name": "张砺", "aliases": ["張礪"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "张砺是滏阳人，曾为郭崇韬掌军书。926年郭被杀后独至魏王府痛哭，随后向任圜建议伏击康延孝。", "biography": null, "status": "draft", "id": "9f51ea48-71ce-5c98-a3af-c7854041f72f"}, {"name": "郭崇韬", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "郭崇韬曾受后唐庄宗赐铁券，后来被杀并遭灭族。928年李嗣源谈铁券时回顾其遭遇，不是当年新发生的处刑。", "biography": null, "status": "draft", "id": "f40abb65-9011-521b-9374-f7cc51e6b1a3"}, {"name": "郭从谦", "aliases": ["郭從謙", "郭门高", "郭門高"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "郭从谦曾任从马直指挥使。927年获任景州刺史，到任后朝廷派人将他族诛。", "biography": null, "status": "draft", "id": "8cbcc8ac-4f16-54f0-89a2-51461b35ae14"}, {"name": "任圜", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "任圜曾任后唐宰相并主管三司。927年先辞三司，后罢相、退休居磁州，十月遭赐死。", "biography": null, "status": "draft", "id": "d266bcef-40af-582b-aca0-b06eb16b5b78"}, {"name": "何建崇", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "何建崇是任圜部将。926年攻下剑门关，《旧五代史》还记他追擒康延孝。", "biography": null, "status": "draft", "id": "4fe39ffa-d23a-5e9c-a368-3c73af2aafb6"}, {"name": "梁汉颙", "aliases": ["梁漢顒"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "梁汉颙是征蜀军都指挥使，926年与任圜、监军李廷安追讨康延孝。", "biography": null, "status": "draft", "id": "e4bf4e21-06bd-5873-b779-582ecb8e0b16"}, {"name": "李廷安", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "李廷安曾任征蜀行营都监，也见为魏王通谒。926年献蜀乐工并参与追讨康延孝，《通鉴》李延安按同职同事辨识，异文保留。", "biography": null, "status": "draft", "id": "3d318885-0f37-5aa6-8167-b87143133c9e"}, {"name": "李环", "aliases": ["李環"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "李环是魏王李继岌的从者。926年击杀郭崇韬；后来奉李继岌本人之命，将李继岌缢杀。", "biography": null, "status": "draft", "id": "121c676d-50bb-570c-9fa2-15a637718d8f"}, {"name": "吕知柔", "aliases": ["呂知柔"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "吕知柔是魏王李继岌亲近的宦官。926年李继岌到渭南时，他已逃匿；不与晋阳只具姓氏的吕内养合并。", "biography": null, "status": "draft", "id": "93402927-a9cd-5743-a1f8-cc845cf3800e"}, {"name": "李仁罕", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "李仁罕是后蜀将领，曾任卫圣诸军都指挥使、武信节度使。934年十月，孟昶命武士将他逮捕并杀死。", "biography": null, "status": "draft", "id": "7059bea3-bcb1-5a3a-9891-bd820251d3d8"}, {"name": "孟知祥", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "孟知祥是后蜀君主。925年，后唐任命他为西川节度使、同平章事。", "biography": null, "status": "draft", "id": "07a6bbea-9699-5f43-aef3-481401e2ed5e"}, {"name": "赵廷隐", "aliases": ["趙廷隱"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "赵廷隐是后蜀将领，曾任左匡圣都指挥使、保宁节度使。934年九月，他兼任侍中，作为李仁罕管理六军事务的副手。", "biography": null, "status": "draft", "id": "bc139832-e17d-51c1-b2c5-a6b9fcca1a14"}, {"name": "张业", "aliases": ["張業"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "张业是后蜀将领。934年四月甲申，率兵进入兴元、洋州。", "biography": null, "status": "draft", "id": "79f0f8ee-f0c7-5ba0-a428-aacf648664be"}, {"name": "李肇", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "李肇是后蜀将领，曾任奉銮肃卫都指挥使、昭武节度使，兼侍中。934年十月，他以太子少傅身份退休，被迁往邛州。", "biography": null, "status": "draft", "id": "9237cc9f-8c36-57a8-86bf-dbf68d5efac9"}, {"name": "侯弘实", "aliases": ["侯弘實"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "侯弘实是后蜀奉銮肃卫指挥副使。934年七月，受孟知祥临终托付，被召参与辅政。", "biography": null, "status": "draft", "id": "7d99ac28-aefc-5060-9209-61de1ecc0b74"}, {"name": "张虔钊", "aliases": ["張虔釗"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "张虔钊曾任山南西道节度使。934年与孙汉韶举家迁往成都；后蜀再次任命他为山南西道节度使、同平章事，他坚持辞谢，没有赴任。", "biography": null, "status": "draft", "id": "b4b03cda-5958-57ef-b1ca-a5c8e1fb4985"}, {"name": "李嗣源", "aliases": ["李亶", "后唐明宗"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "李存勖麾下的重要将领。参与908年潞州解围，923年袭取郓州并率前军进入大梁。", "biography": "李存勖麾下的重要将领。参与908年潞州解围，923年袭取郓州并率前军进入大梁。", "status": "draft", "id": "5d1886ff-b3ec-56f6-a154-b5633c294037"}, {"name": "高行周", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "高行周曾受兄长高行珪派遣，到晋军中做人质，争取援兵。", "biography": null, "status": "draft", "id": "659c5f83-09bc-5282-8f02-4c7fa0a62729"}, {"name": "安重诲", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "安重诲曾任后唐枢密使兼中书令，后调任护国节度使。931年闰五月退休后，李从璋接任护国节度使，在河中将他和妻子张氏杀死。朝廷随后列举罪名，并处死他的二子。", "biography": null, "status": "draft", "id": "ce1aed16-1e3c-550a-954b-f37ff4743d0c"}, {"name": "李琼（隐光）", "aliases": ["李瓊（隱光）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "李琼字隐光，沧州饶安人，曾隶李嗣源麾下。926年受石敬瑭指挥先入封丘门，与已去世的楚将李琼分别建主体。", "biography": null, "status": "draft", "id": "3e1aa0f4-6823-52ac-87cb-13fa2ad13848"}, {"name": "石敬瑭", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "石敬瑭曾与后梁军交战，遇险时得到刘知远让出战马相助。", "biography": null, "status": "draft", "id": "bf42d98c-7477-5be1-a767-867fe26cf617"}, {"name": "张昭（五代宋初）", "aliases": ["张昭远", "張昭遠"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "张昭本名昭远，后避汉祖名讳而改称张昭。928年以史馆修撰身份建议为皇子择师、区分礼遇；李嗣源赞叹，但未采用。", "biography": null, "status": "draft", "id": "0f1b47dc-df4b-5258-91b3-463432d576b7"}, {"name": "张宪", "aliases": ["張憲"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "张宪曾任北京留守。926年拒绝赵在礼招诱与劝进，晋阳变后逃离，后被赐死；《新五代史》对去向和死因记法提出疑问。", "biography": null, "status": "draft", "id": "d183a261-d982-5928-a283-ae6c485e0f5b"}, {"name": "孙光宪", "aliases": ["孫光憲"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "孙光宪是贵平人，曾任陵州判官。《资治通鉴》记载，926年梁震向高季兴推荐他，他被任命为掌书记。", "biography": null, "status": "draft", "id": "76582a2a-2b64-57f9-abd9-a6f9aabed78f"}, {"name": "高季昌", "aliases": ["高季兴"], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "高季昌是荆南统治者，后改名高季兴。907年获任荆南节度使。", "biography": null, "status": "draft", "id": "e1d9e2c4-6e41-5d7c-8d65-eb79a2407418"}, {"name": "朱弘昭", "aliases": ["硃弘昭"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "朱弘昭是太原人，曾任后唐文思使、东川副使。《资治通鉴》认为他与孟汉琼等人挑起猜疑离间，使李从厚遭遇祸败；这是史家归因。", "biography": null, "status": "draft", "id": "b16a5dfd-a78d-54bb-99a3-cd8af4e8da0b"}, {"name": "董璋", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "董璋曾任东川节度使，932年出兵攻西川。汉州战败后逃回梓州，被潘稠杀死；《旧五代史》概述为王晖率众杀害，各书执行层次分别保留。", "biography": null, "status": "draft", "id": "ecbba4d7-b26a-5c43-ad24-180221fafb2b"}, {"name": "边蔚", "aliases": ["邊蔚"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "边蔚是长安人、毛璋观察判官。926年毛璋想抗命时，他与李承约劝说毛璋接受替代。", "biography": null, "status": "draft", "id": "c33252cc-2683-5c11-afc6-b572a2bc06d4"}, {"name": "毛璋", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "毛璋曾任昭义节度使。史书记他穿赭袍、纵酒扮戏的僭越行为；928年被征为右金吾卫上将军。", "biography": null, "status": "draft", "id": "54d0ec27-abd0-5745-9499-3508feb9bca4"}, {"name": "李承约", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“王思同、李承约等离开幽州投奔河东”中为归附者。", "biography": null, "status": "draft", "id": "5ac383c0-e004-5170-af89-786cc2ec0e31"}, {"name": "韩延徽", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "韩延徽曾仕契丹。《资治通鉴》在德光继位段记他任政事令，《辽史》另记太祖时已有此职，实际任职阶段分别保留。", "biography": null, "status": "draft", "id": "0ca1edb4-4ddc-5483-b6ab-1513e30cf800"}, {"name": "耶律德光", "aliases": ["德光"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》同光四年条记载耶律德光守卫西楼，称号为元帅太子。", "biography": null, "status": "draft", "id": "64c415ac-57fe-571c-8c6f-3ed68fb726da"}, {"name": "阿保机", "aliases": ["耶律阿保机", "耶律阿保機", "邪律阿保机", "邪律阿保機", "阿保機"], "era": "晚唐", "birth_year": null, "death_year": null, "description": "阿保机是契丹统治者。死后葬期与葬地，《资治通鉴》及《辽史》的记法不同，分别保留。", "biography": null, "status": "draft", "id": "c632d829-b418-5526-94fd-cc14fddaa9bd"}, {"name": "李存乂", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "李存乂是庄宗之弟、郭崇韬女婿，封睦王。926年为郭称冤受宦官指控，先幽禁后被杀；与郭从谦为养父子。", "biography": null, "status": "draft", "id": "ec79ce39-72f2-52ef-96c8-42b3dedcffd8"}, {"name": "安审通", "aliases": ["安審通"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "安审通曾任横海节度使、北面副招讨使，参与讨伐定州。928年七月去世，《旧五代史》记卒于军中，未说明具体死因。", "biography": null, "status": "draft", "id": "8b318de0-b3e7-5558-9ffc-658558bd9126"}, {"name": "安金全", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "代北人，曾任骑将。907年梁军围攻潞州时，随周德威率领的晋军前往救援。", "biography": null, "status": "draft", "id": "b52eca39-fd61-599b-8624-160fbb4ec282"}, {"name": "李从璋", "aliases": ["李從璋"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "李从璋封洋王，曾任后唐护国节度使。934年的记载说，他离任后住在洛阳私宅。", "biography": null, "status": "draft", "id": "582991ae-1cfa-5499-93e5-b5a7e4859997"}, {"name": "刘氏（王宗衍妾）", "aliases": ["劉氏（王宗衍妾）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "刘氏是王宗衍的妾。《新五代史》记秦川驿行刑时她拒绝免死、选择就死，不能与庄宗刘皇后混同。", "biography": null, "status": "draft", "id": "918e67e9-8569-5046-97ae-27845e4e9763"}, {"name": "王宗衍", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "王宗衍即前蜀君主王衍。《资治通鉴》记928年追赠顺正公，准许以诸侯礼安葬；实际下葬日期另有不同记述。", "biography": null, "status": "draft", "id": "833f9aac-6321-5267-9e81-3e9756dfafc8"}, {"name": "伊氏（李存勖德妃）", "aliases": ["伊德妃"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "伊氏是李存勖德妃。926年李嗣源命朱守殷丰备她与淑妃的宫中供给，不与后梁张德妃合并。", "biography": null, "status": "draft", "id": "daf0d7c6-6365-519b-a418-1b5d8efab4cb"}, {"name": "李存勖", "aliases": ["李存勗", "李亚子", "后唐庄宗"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "908年继承晋王之位，923年在魏州称帝，国号唐；同年率军灭后梁。", "biography": "908年继承晋王之位，923年在魏州称帝，国号唐；同年率军灭后梁。", "status": "draft", "id": "4e068da9-c8dd-5a31-a747-87669e3bf993"}, {"name": "皇甫晖", "aliases": ["皇甫暉"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "皇甫晖参与魏州牙兵之乱。927年朝廷为调整邺都军务，任命他为陈州刺史。", "biography": null, "status": "draft", "id": "a1bbff11-3e05-52a8-a3c1-7e24adc029a5"}, {"name": "杨仁晸", "aliases": ["楊仁晸"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "杨仁晸是魏博指挥使，率戍瓦桥的轮替归兵留驻贝州。926年拒绝皇甫晖胁迫，被杀。", "biography": null, "status": "draft", "id": "81024336-a9b4-57d1-b437-4c8693e55c60"}, {"name": "焦武", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "焦武是康延孝所部河中将领。926年哭诉朱友谦案，担心东归受诛，表示不再东行。", "biography": null, "status": "draft", "id": "f84b0087-a3ac-5ce8-9f52-3bf961e72c46"}, {"name": "康延孝", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "康延孝曾获赐名李绍琛。平蜀后领后军，926年因郭崇韬、朱友谦案心生疑惧，率兵返蜀，败于任圜后在凤翔被处决。", "biography": null, "status": "draft", "id": "1aa78b3e-f7ca-5dbd-bb5c-9c3db6cbc3b2"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person_relationship (id, person_a, person_b, relation_type, description, status)
SELECT id, person_a, person_b, relation_type, description, status FROM jsonb_populate_recordset(NULL::public.person_relationship, '[{"relation_type": "都统推官", "description": "李崧是魏王李继岌军中的都统推官，926年曾反对擅杀郭崇韬。", "status": "draft", "id": "653368fe-53ef-5d0a-a2c0-66b13e1b17c7", "person_a": "42727c37-29c7-534f-b0f7-900992c16def", "person_b": "d160654e-338c-57b1-9759-208ae0af8250"}, {"relation_type": "掌书记", "description": "张砺是郭崇韬掌书记；《旧五代史》明记郭崇韬奏请张砺掌军书。原文私用字与规范名分别保留。", "status": "draft", "id": "97b961ea-cc55-5da1-b78a-0520143d268d", "person_a": "9f51ea48-71ce-5c98-a3af-c7854041f72f", "person_b": "f40abb65-9011-521b-9374-f7cc51e6b1a3"}, {"relation_type": "义叔父", "description": "郭从谦以叔父礼事郭崇韬，《新五代史》说因同姓郭而拜他为叔父。郭崇韬是郭从谦的义叔父，不是已证血缘叔父。", "status": "draft", "id": "7164ecaa-d390-54b5-819c-11f3bcae3b96", "person_a": "f40abb65-9011-521b-9374-f7cc51e6b1a3", "person_b": "8cbcc8ac-4f16-54f0-89a2-51461b35ae14"}, {"relation_type": "副招讨使", "description": "任圜获魏王李继岌任为副招讨使，926年率兵追讨康延孝；任职起止未详。", "status": "draft", "id": "53b9c10a-03ab-51c9-907f-c4c2e2e5d365", "person_a": "d266bcef-40af-582b-aca0-b06eb16b5b78", "person_b": "d160654e-338c-57b1-9759-208ae0af8250"}, {"relation_type": "部将", "description": "何建崇是任圜部将，926年受命攻下剑门关。", "status": "draft", "id": "f3eb20db-32dd-5807-916a-270f29f7e6a3", "person_a": "4fe39ffa-d23a-5e9c-a368-3c73af2aafb6", "person_b": "d266bcef-40af-582b-aca0-b06eb16b5b78"}, {"relation_type": "都指挥使", "description": "梁汉颙是李继岌军中的都指挥使，926年与任圜、监军一同追讨康延孝。", "status": "draft", "id": "8d57fa50-0ca1-5d0b-afc7-1dfd612a2305", "person_a": "e4bf4e21-06bd-5873-b779-582ecb8e0b16", "person_b": "d160654e-338c-57b1-9759-208ae0af8250"}, {"relation_type": "通谒", "description": "李廷安是魏王李继岌的通谒，926年献蜀地乐工；另有行营都监职称，依各书分别保存。", "status": "draft", "id": "475345ea-8f0f-5326-b84b-5ae33537a735", "person_a": "3d318885-0f37-5aa6-8167-b87143133c9e", "person_b": "d160654e-338c-57b1-9759-208ae0af8250"}, {"relation_type": "从者", "description": "李环是李继岌从者，926年郭崇韬登楼阶时被李环击杀。具体任职始终年月未载。", "status": "draft", "id": "f94a8d1e-0f6b-539c-8a80-2a6b97bb1cdc", "person_a": "121c676d-50bb-570c-9fa2-15a637718d8f", "person_b": "d160654e-338c-57b1-9759-208ae0af8250"}, {"relation_type": "亲信", "description": "吕知柔是李继岌腹心亲近者，926年李继岌到渭南时已经逃匿，不与晋阳吕内养合并。", "status": "draft", "id": "784d4a27-afbe-59f6-8b75-458070d058f7", "person_a": "93402927-a9cd-5743-a1f8-cc845cf3800e", "person_b": "d160654e-338c-57b1-9759-208ae0af8250"}, {"relation_type": "马步都指挥使", "description": "李仁罕是孟知祥的马步都指挥使，926年受命率兵讨康延孝。", "status": "draft", "id": "176d79b0-e577-5a98-8016-877f681b9013", "person_a": "7059bea3-bcb1-5a3a-9891-bd820251d3d8", "person_b": "07a6bbea-9699-5f43-aef3-481401e2ed5e"}, {"relation_type": "左厢都指挥使", "description": "赵廷隐是孟知祥左厢都指挥使，926年受命分兵讨蜀地群盗。", "status": "draft", "id": "08b73b9b-c6f1-5794-a427-f56e3e545033", "person_a": "bc139832-e17d-51c1-b2c5-a6b9fcca1a14", "person_b": "07a6bbea-9699-5f43-aef3-481401e2ed5e"}, {"relation_type": "右厢都指挥使", "description": "张业是孟知祥右厢都指挥使，926年受命分兵讨蜀地群盗。", "status": "draft", "id": "cd0e75cc-aff6-591a-bd64-b442ff6824bb", "person_a": "79f0f8ee-f0c7-5ba0-a428-aacf648664be", "person_b": "07a6bbea-9699-5f43-aef3-481401e2ed5e"}, {"relation_type": "牙内马步都指挥使", "description": "孟知祥任李肇为牙内马步都指挥使，926年康延孝败后见于原文；此前职务与这次任命分阶段。", "status": "draft", "id": "ea3c7d45-29ad-585d-90d7-2e84317438cb", "person_a": "9237cc9f-8c36-57a8-86bf-dbf68d5efac9", "person_b": "07a6bbea-9699-5f43-aef3-481401e2ed5e"}, {"relation_type": "副指挥使", "description": "孟知祥任侯弘实为李肇的副手，属于牙内马步指挥体系；原文只说弘实副之，不补造更长的正式官告名。", "status": "draft", "id": "671b1caf-5cad-5265-a55d-09614ef3d1ff", "person_a": "7d99ac28-aefc-5060-9209-61de1ecc0b74", "person_b": "07a6bbea-9699-5f43-aef3-481401e2ed5e"}, {"relation_type": "牙将", "description": "张虔钊是李嗣源牙将，926年受命召元行钦合力平乱。", "status": "draft", "id": "46e9795c-8681-5fb8-b825-893de294e0af", "person_a": "b4b03cda-5958-57ef-b1ca-a5c8e1fb4985", "person_b": "5d1886ff-b3ec-56f6-a154-b5633c294037"}, {"relation_type": "牙将", "description": "高行周是李嗣源牙将，926年受命召元行钦合力平乱。", "status": "draft", "id": "5bf5ee81-fc42-5f96-a5b9-5cea012fba5c", "person_a": "659c5f83-09bc-5282-8f02-4c7fa0a62729", "person_b": "5d1886ff-b3ec-56f6-a154-b5633c294037"}, {"relation_type": "中门使", "description": "安重诲是李嗣源的中门使，926年在魏县劝李嗣源赶赴京城；后来枢密使任命是另一阶段。", "status": "draft", "id": "4c857b44-ec76-5b9f-ae72-b1cd620e9271", "person_a": "ce1aed16-1e3c-550a-954b-f37ff4743d0c", "person_b": "5d1886ff-b3ec-56f6-a154-b5633c294037"}, {"relation_type": "裨将", "description": "李琼字隐光，是石敬瑭裨将，926年受命先入汴州封丘门；与已经去世的楚将李琼是不同主体。", "status": "draft", "id": "6e3d20a5-5816-5a0e-903e-26c99700e1c9", "person_a": "3e1aa0f4-6823-52ac-87cb-13fa2ad13848", "person_b": "bf42d98c-7477-5be1-a767-867fe26cf617"}, {"relation_type": "推官", "description": "张昭远即五代宋初张昭，是张宪推官。《宋史》明记张宪署他为府推官，后随张宪到晋阳。", "status": "draft", "id": "defd6fc6-e41c-546f-82da-22014fbd250f", "person_a": "0f1b47dc-df4b-5258-91b3-463432d576b7", "person_b": "d183a261-d982-5928-a283-ae6c485e0f5b"}, {"relation_type": "掌书记", "description": "高季昌又名高季兴，926年经梁震推荐任孙光宪为掌书记；《宋史》高从诲任从事是另一段经历，不合为同次任命。", "status": "draft", "id": "87904198-790b-5605-b2c0-333341157fc0", "person_a": "76582a2a-2b64-57f9-abd9-a6f9aabed78f", "person_b": "e1d9e2c4-6e41-5d7c-8d65-eb79a2407418"}, {"relation_type": "副使", "description": "朱弘昭获任董璋所镇东川的副使，926年见任命。《新五代史》也明记董璋为东川节度使、以弘昭为副使；未知任职起止留空。", "status": "draft", "id": "9523c051-3722-57ce-8782-6d8bc6061187", "person_a": "b16a5dfd-a78d-54bb-99a3-cd8af4e8da0b", "person_b": "ecbba4d7-b26a-5c43-ad24-180221fafb2b"}, {"relation_type": "观察判官", "description": "边蔚是毛璋的观察判官，926年劝毛璋接受替代。《旧五代史》毛璋传、《新五代史》毛璋传均明确其判官身份。", "status": "draft", "id": "33fa8e08-5ef3-5c4a-aa7e-26250d1aff28", "person_a": "c33252cc-2683-5c11-afc6-b572a2bc06d4", "person_b": "54d0ec27-abd0-5745-9499-3508feb9bca4"}, {"relation_type": "节度副使", "description": "李承约受朝廷任为毛璋节度副使以监察他，不是由共同作战推为私人亲信。《资治通鉴》承静难军，《旧五代史》李传称泾州副使，官镇差异保留。", "status": "draft", "id": "727504dd-4470-5d45-86ac-2acc68dfac31", "person_a": "5ac383c0-e004-5170-af89-786cc2ec0e31", "person_b": "54d0ec27-abd0-5745-9499-3508feb9bca4"}, {"relation_type": "政事令", "description": "《资治通鉴》在耶律德光继位段记韩延徽任政事令。《辽史》另载他在阿保机时期已获守政事令，不据这句断定首次任职或虚构罢复任。", "status": "draft", "id": "744bded9-621e-57bf-84b0-f924c946bac9", "person_a": "0ca1edb4-4ddc-5483-b6ab-1513e30cf800", "person_b": "64c415ac-57fe-571c-8c6f-3ed68fb726da"}, {"relation_type": "守政事令", "description": "《辽史》韩延徽传记阿保机命他为守政事令、崇文馆大学士，这是此前任职，具体年份未载，不强定926年。", "status": "draft", "id": "b849a674-cdce-5542-9d67-69e4c91b1446", "person_a": "0ca1edb4-4ddc-5483-b6ab-1513e30cf800", "person_b": "c632d829-b418-5526-94fd-cc14fddaa9bd"}, {"relation_type": "女婿", "description": "李存乂是郭崇韬女婿，原文明确，郭氏女未具名不编姓名，婚期未载。", "status": "draft", "id": "58b4669b-6872-5df9-b2c4-e9b3d6b9b76b", "person_a": "ec79ce39-72f2-52ef-96c8-42b3dedcffd8", "person_b": "f40abb65-9011-521b-9374-f7cc51e6b1a3"}, {"relation_type": "侄子", "description": "安审通是安金全的侄子，原文未分叔伯长幼，不建反向叔父或伯父关系。", "status": "draft", "id": "a41fd6ce-8109-5a62-a1f5-fbb9d2603f2f", "person_a": "8b318de0-b3e7-5558-9ffc-658558bd9126", "person_b": "b52eca39-fd61-599b-8624-160fbb4ec282"}, {"relation_type": "侄子", "description": "李从璋是李嗣源的从子，即侄子，926年自镇州南行。未具父亲和叔伯长幼，不补父系。", "status": "draft", "id": "c51895e4-1084-5b7f-9423-5241d7c0e72e", "person_a": "582991ae-1cfa-5499-93e5-b5a7e4859997", "person_b": "5d1886ff-b3ec-56f6-a154-b5633c294037"}, {"relation_type": "妾", "description": "《新五代史》前蜀世家明确刘氏为王宗衍的妾，婚期与本名未载，不与庄宗刘皇后混同。", "status": "draft", "id": "85955ba2-c74b-5326-87b5-91c647c69c54", "person_a": "918e67e9-8569-5046-97ae-27845e4e9763", "person_b": "833f9aac-6321-5267-9e81-3e9756dfafc8"}, {"relation_type": "妃子", "description": "伊氏是庄宗李存勖的德妃，《新五代史》家人传在924年封妃上下文明示。此处作为926年在宫身份补证，不改为当年新婚。", "status": "draft", "id": "0e02d6b1-e006-5a08-b50f-262b4c83d7fa", "person_a": "daf0d7c6-6365-519b-a418-1b5d8efab4cb", "person_b": "4e068da9-c8dd-5a31-a747-87669e3bf993"}, {"relation_type": "部兵", "description": "皇甫晖原为杨仁晸部兵，926年贝州兵变前见于明确从属称谓。关系限兵变前身份，不推为事后仍服从或私人盟友。", "status": "draft", "id": "44e44cf4-9ab5-55b6-bf4a-803cb33e9e5a", "person_a": "a1bbff11-3e05-52a8-a3c1-7e24adc029a5", "person_b": "81024336-a9b4-57d1-b437-4c8693e55c60"}, {"relation_type": "部将", "description": "焦武是康延孝所领河中军将，926年在军门哭诉朱友谦案。原文康延孝写作李绍琛，身份沿已核同人，不由共同哭诉推永久盟友。", "status": "draft", "id": "72bd57c3-7d88-5a0e-9e43-304692be265b", "person_a": "f84b0087-a3ac-5ce8-9f52-3bf961e72c46", "person_b": "1aa78b3e-f7ca-5dbd-bb5c-9c3db6cbc3b2"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

